+class Email {
+  private constructor(readonly value: string) {}
+  static of(raw: string): Email {
+    // validates once, every caller can then trust it
+    if (!raw.includes('@')) throw new Error('invalid email');
+    return new Email(raw);
+  }
+}
+
+class FirstName {
+  constructor(readonly value: string) {}   // any string is a valid first name
+}
+class LastName {
+  constructor(readonly value: string) {}   // ditto
+}
+
+class Age {
+  constructor(readonly value: number) {}   // no check: accepts -3 and 900
+}
+
 // usage
 const u = {
   email: Email.of(form.email),
-  firstName: form.firstName,
+  firstName: new FirstName(form.firstName),
+  lastName: new LastName(form.lastName),
+  age: new Age(Number(form.age)),
 };
